package corpus.rangeeach

fun sumStoredRange(limit: Int): Int {
    val range = 0..<limit
    var total = 0
    range.forEach { total += it }
    return total
}

package corpus.rangeeach

fun sumMaterializedList(limit: Int): Int {
    var total = 0
    (0..<limit).toList().forEach { total += it }
    return total
}

package corpus.rangeeach

fun sumMethodRange(limit: Int): Int {
    var total = 0
    ((0.rangeTo(limit))).forEach { total += it }
    return total
}
